module addpipe32 (
    input  wire        clk,
    input  wire        rst_n,
    input  wire        valid_i,
    input  wire [31:0] a_i,
    input  wire [31:0] b_i,
    output reg         valid_o,
    output reg  [31:0] y_o
);

wire [31:0] p0 = a_i ^ b_i;
wire [31:0] g0 = a_i & b_i;

// Sklansky (divide and conquer) prefix
wire [191:0] gv;
wire [191:0] pv;
assign gv[31:0] = g0;
assign pv[31:0] = p0;

genvar l, i;
generate
  for (l = 1; l <= 5; l = l + 1) begin : lev
    for (i = 0; i < 32; i = i + 1) begin : bslc
