        localparam integer BASE = ((i >> (l-1)) << (l-1)) - 1;
        assign gv[l*32+i] = gv[(l-1)*32+i] | (pv[(l-1)*32+i] & gv[(l-1)*32+BASE]);
        assign pv[l*32+i] = pv[(l-1)*32+i] & pv[(l-1)*32+BASE];
      end else begin : pass
        assign gv[l*32+i] = gv[(l-1)*32+i];
        assign pv[l*32+i] = pv[(l-1)*32+i];
      end
    end
  end
endgenerate

